"""Four original RGB source views for the road/follow construction.

The caller supplies lossless frame sinks. This helper checks frame identity and
resolution; only subsequent physical review can establish visibility.
"""

from collections import defaultdict
from pathlib import Path
import subprocess
from threading import Condition
from time import monotonic


CAMERAS = {
    'overview': ((-8.0, 0.0, 7.0), (-20.0, 0.0, 0.0), (1920, 1080), 95),
    'approach': ((1.5, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    'reference_corner': ((1.5, 1.0, 1.6), (0.0, 0.0, 0.0), (1280, 720), 100),
    'driver_reference': ((0.3, -0.3, 1.5), (0.0, 0.0, 0.0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError('Unknown following source camera')
        path = Path(output) / (name + '.mkv')
        if path.exists():
            raise ValueError('Retain prior following camera source')
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen([
            'ffmpeg', '-nostdin', '-loglevel', 'error', '-y',
            '-f', 'rawvideo', '-pixel_format', 'bgra',
            '-video_size', f'{width}x{height}', '-framerate', '20',
            '-i', 'pipe:0', '-an', '-c:v', 'ffv1', str(path)],
            stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError('Original following camera byte count changed')
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError('Following source encoder failed')


class FollowingCameraCapture:
    def __init__(self, world, carla, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError('Four named source-camera sinks required')
        self.sensors = []
        self.frames = defaultdict(list)
        self.sinks = sinks
        self.condition = Condition()
        self.errors = []
        self.closed = False
        try:
            for name, (location, rotation, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
                blueprint.set_attribute('image_size_x', str(size[0]))
                blueprint.set_attribute('image_size_y', str(size[1]))
                blueprint.set_attribute('fov', str(fov))
                blueprint.set_attribute('sensor_tick', '0.05')
                transform = carla.Transform(carla.Location(*location),
                                            carla.Rotation(*rotation))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                if sensor is None:
                    raise ValueError('Could not spawn source camera: ' + name)
                self.sensors.append(sensor)
                sensor.listen(self._listener(name, size))
        except BaseException:
            self.close()
            raise

    def _listener(self, name, size):
        def receive(image):
            with self.condition:
                if self.closed:
                    return
                try:
                    if (image.width, image.height) != size:
                        raise ValueError('Source camera resolution changed: ' + name)
                    if image.frame in self.frames[name]:
                        raise ValueError('Duplicate original source camera frame: ' + name)
                    self.sinks[name].write(image)
                    self.frames[name].append(image.frame)
                except BaseException as error:
                    self.errors.append(error)
                finally:
                    self.condition.notify_all()
        return receive

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError('Source camera callback failed') from self.errors[0]
                if all(frame in self.frames[name] for name in CAMERAS):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError('Missing original source camera frame')
                self.condition.wait(remaining)

    def verify(self, expected_frames):
        if not expected_frames or self.errors:
            raise ValueError('No original Native frames to verify')
        for name in CAMERAS:
            if self.frames[name] != expected_frames:
                raise ValueError('Missing or extra original source camera frames: ' + name)
        return {name: len(expected_frames) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                try:
                    sensor.stop()
                finally:
                    sensor.destroy()

"""Measure candidate NRS 484B.650(1) event windows from original sources.

Input event labels are cited review hypotheses. This code checks their timing and
path span; it does not decide any predicate violation or immediate-hazard law.
"""

from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path


MILE_M = 1609.344
PREDICATES = {'device', 'off_pavement_right_pass', 'marked_lane',
              'too_close', 'yield'}
CATEGORIES = PREDICATES | {'speed', 'hazard'}


def _load(path):
    path = Path(path)
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing original source: ' + path.name)
    raw = path.read_bytes()
    try:
        return raw, sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original source: ' + path.name) from error


def _trace(path):
    raw, digest = _load(path)
    try:
        rows = [json.loads(line) for line in raw.splitlines()]
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original trace') from error
    if len(rows) < 3:
        raise ValueError('Continuous original driving trace needs three frames')
    cumulative = [0.0]
    previous = None
    for row in rows:
        try:
            frame, time_s = row['frame'], float(row['time_s'])
            x, y = float(row['x_m']), float(row['y_m'])
        except (KeyError, TypeError, ValueError) as error:
            raise ValueError('Original driving frame/position missing') from error
        if type(frame) is not int or not all(isfinite(v) for v in (time_s, x, y)):
            raise ValueError('Original driving frame/position invalid')
        if previous is not None:
            if frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > 1e-4:
                raise ValueError('Original driving trace is not continuous at 20 Hz')
            cumulative.append(cumulative[-1] + hypot(x - previous[2], y - previous[3]))
        previous = frame, time_s, x, y
    return rows, cumulative, digest


def measure(trace_path, event_path, source_root):
    trace, distance, trace_sha = _trace(trace_path)
    raw, event_sha = _load(event_path)
    try:
        events = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid event annotation source') from error
    if not isinstance(events, list):
        raise ValueError('Event annotation source must be a list')
    first = trace[0]['frame']
    roots = Path(source_root).resolve()
    seen, citations = set(), {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('Event annotation is not an object')
        category, occurrence = event.get('category'), event.get('occurrence_id')
        frame, ref, digest = event.get('frame'), event.get('source_ref'), event.get('source_sha256')
        if category not in CATEGORIES or not isinstance(occurrence, str) or not occurrence or occurrence in seen:
            raise ValueError('Event category or occurrence identity invalid')
        seen.add(occurrence)
        if type(frame) is not int or frame < first or frame >= first + len(trace):
            raise ValueError('Event outside original continuous driving frames')
        if not isinstance(ref, str) or not ref or not isinstance(digest, str):
            raise ValueError('Event needs a source citation')
        source = (roots / ref).resolve()
        if not source.is_relative_to(roots) or not source.is_file():
            raise ValueError('Event source outside retained source root')
        actual = sha256(source.read_bytes()).hexdigest()
        if actual != digest:
            raise ValueError('Event source hash differs')
        citations[ref] = actual
        if category == 'hazard' and event.get('target_type') not in ('person', 'vehicle'):
            raise ValueError('Hazard target must be a person or vehicle')
    events.sort(key=lambda item: (item['frame'], item['occurrence_id']))
    candidates = []
    for left in range(len(events)):
        speed = hazard = acts = 0
        for right in range(left, len(events)):
            category = events[right]['category']
            speed += category == 'speed'
            hazard += category == 'hazard'
            acts += category in PREDICATES
            start, end = events[left]['frame'], events[right]['frame']
            span_m = distance[end - first] - distance[start - first]
            if span_m > MILE_M:
                break
            if speed and hazard and acts >= 2:
                candidates.append((span_m, start, end, left, right))
                break
    best = min(candidates) if candidates else None
    selected = events[best[3]:best[4] + 1] if best else []
    predicate_categories = [item['category'] for item in selected if item['category'] in PREDICATES]
    return {
        'format': 'worker-aggressive-driving-window-observation',
        'sources': {'driving_trace.jsonl': trace_sha, 'event_annotations.json': event_sha,
                    **citations},
        'original_frame_count': len(trace), 'total_driving_path_m': distance[-1],
        'candidate_window': None if best is None else {
            'start_frame': best[1], 'end_frame': best[2], 'path_m': best[0],
            'event_occurrence_ids': [item['occurrence_id'] for item in selected],
            'predicate_categories': predicate_categories,
            'repeated_predicate_category': len(predicate_categories) > len(set(predicate_categories)),
            'hazard_target_types': [item['target_type'] for item in selected if item['category'] == 'hazard']},
        'predicate_violation_judgments': None,
        'immediate_hazard_legal_judgment': None,
        'aggressive_driving_legal_judgment': None,
    }

from pathlib import Path
from types import SimpleNamespace as NS
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from following_cameras import CAMERAS, FollowingCameraCapture


class Blueprint:
    def __init__(self):
        self.attributes = {}

    def set_attribute(self, key, value):
        self.attributes[key] = value


class Sensor:
    def listen(self, callback):
        self.callback = callback

    def stop(self):
        self.stopped = True

    def destroy(self):
        self.destroyed = True


class Sink:
    def __init__(self):
        self.frames = []

    def write(self, image):
        self.frames.append(image.frame)


class World:
    def __init__(self):
        self.blueprints = []
        self.sensors = []

    def get_blueprint_library(self):
        def find(name):
            self.blueprints.append((name, Blueprint()))
            return self.blueprints[-1][1]
        return NS(find=find)

    def spawn_actor(self, blueprint, transform, attach_to):
        sensor = Sensor()
        self.sensors.append(sensor)
        return sensor


class CameraTests(unittest.TestCase):
    def test_four_named_original_streams_and_rejection(self):
        world = World()
        carla = NS(Location=lambda *values: values,
                   Rotation=lambda *values: values,
                   Transform=lambda location, rotation: (location, rotation))
        sinks = {name: Sink() for name in CAMERAS}
        capture = FollowingCameraCapture(world, carla, object(), sinks)
        self.assertEqual(len(world.sensors), 4)
        self.assertTrue(all(name == 'sensor.camera.rgb' for name, _ in world.blueprints))
        for sensor, (name, spec) in zip(world.sensors, CAMERAS.items()):
            width, height = spec[2]
            sensor.callback(NS(frame=20, width=width, height=height))
        self.assertEqual(capture.verify([20]), {name: 1 for name in CAMERAS})
        with self.assertRaisesRegex(ValueError, 'Missing or extra'):
            capture.verify([20, 21])
        capture.close()
        self.assertTrue(all(sensor.destroyed and sensor.stopped
                            for sensor in world.sensors))


if __name__ == '__main__':
    unittest.main()
